// First find all neighbors of current node if not already found
if (current_node->neighbors.empty()) {
    current_node->find_neighbors();
}

// Calculate h value for each neighbor
for (auto neighbor : current_node->neighbors) {
    if (!neighbor->visited) {
        // Calculate g value: current g + distance to neighbor
        float g_value = current_node->g_value + current_node->distance(*neighbor);

        // Calculate h value: heuristic distance to end node
        float h_value = std::numeric_limits<float>::max();
        if (neighbor != end_node) {
            h_value = calc_h_value(neighbor);
        }

        // Create a new node with updated values
        RouteModel::Node* new_node = new RouteModel::Node(*neighbor);
        new_node->parent = current_node;
        new_node->g_value = g_value;
        new_node->h_value = h_value;

        // Add to open list
        open_list_.push_back(new_node);
    }
}

